import{_ as n,o as h,c as o,a3 as g}from"./chunks/framework.MGD2uYU7.js";const l=JSON.parse('{"title":"06 — Yêu cầu pháp lý & phân định trách nhiệm (AP ↔ MAYogu)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-legal.md","filePath":"guide/06-legal.md","lastUpdated":null}'),r={name:"guide/06-legal.md"};function d(c,t,i,s,e,a){return h(),o("div",null,[...t[0]||(t[0]=[g('<h1 id="_06-—-yeu-cau-phap-ly-phan-đinh-trach-nhiem-ap-↔-mayogu" tabindex="-1">06 — Yêu cầu pháp lý &amp; phân định trách nhiệm (AP ↔ MAYogu) <a class="header-anchor" href="#_06-—-yeu-cau-phap-ly-phan-đinh-trach-nhiem-ap-↔-mayogu" aria-label="Permalink to &quot;06 — Yêu cầu pháp lý &amp; phân định trách nhiệm (AP ↔ MAYogu)&quot;">​</a></h1><p><strong>Dự án</strong>: Hệ thống phần mềm &amp; website cho CĐT An Phúc — dự án An Phúc Imperia <strong>Status</strong>: Draft gửi khách hàng rà soát — <strong>Updated</strong>: 2026-10-11 — <strong>Version</strong>: 2.0 <strong>Mảng</strong>: G — Legal · <strong>Mã module</strong>: <code>LEG</code><strong>Nguồn</strong>: Sheet <code>05_LEGAL</code> (Google Sheet MAYogu × An Phúc). Cột gốc: <strong>STT | Tính năng | Nội dung pháp lý | AP | MAYogu</strong>.</p><blockquote><p>Bản đặc tả trung thực của sheet: bám sát từng dòng, giữ nguyên ngôn từ pháp lý. Không tự thêm điều khoản/văn bản luật ngoài sheet. Mục chưa có nội dung chi tiết đánh dấu 🟡; đề xuất chưa duyệt đánh dấu 🔵.</p></blockquote><p><strong>Quy ước hai bên (dùng trong toàn doc):</strong></p><ul><li><strong>AP</strong> = <strong>Chủ đầu tư An Phúc</strong> (CTCP Phát triển nhà ở xã hội An Phúc) — bên chịu trách nhiệm pháp lý chính, đứng tên doanh nghiệp.</li><li><strong>MAYogu</strong> = đơn vị phát triển phần mềm/website — bên triển khai kỹ thuật.</li><li>Cột <strong>&quot;Ai chịu trách nhiệm&quot;</strong> ghi nguyên văn phân định trong sheet. <strong>Nội dung pháp lý</strong> chỉ mang tính tổng hợp yêu cầu, không thay thế tư vấn luật sư (AP dùng luật sư riêng — mục 5).</li></ul><hr><h2 id="_1-tom-tat-9-muc-phap-ly-sheet-05" tabindex="-1">1. Tóm tắt 9 mục pháp lý (Sheet 05) <a class="header-anchor" href="#_1-tom-tat-9-muc-phap-ly-sheet-05" aria-label="Permalink to &quot;1. Tóm tắt 9 mục pháp lý (Sheet 05)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>STT</th><th>Tính năng / hạng mục</th><th>Văn bản pháp lý viện dẫn (nguyên văn)</th><th>Trách nhiệm chính</th></tr></thead><tbody><tr><td>1</td><td>Thu thập thông tin định danh</td><td>Nghị định 13/2023/NĐ-CP (bảo vệ dữ liệu cá nhân)</td><td><strong>AP</strong></td></tr><tr><td>2</td><td>Đăng ký mua (website TMĐT)</td><td>Quy định đăng ký TMĐT — Bộ Công Thương (online.gov.vn)</td><td><strong>AP</strong></td></tr><tr><td>3</td><td>Minh bạch thông tin</td><td>Luật Kinh doanh BĐS 2023; Luật Nhà ở 2023</td><td><strong>AP</strong></td></tr><tr><td>4</td><td>Bảo mật và ATTT</td><td>(cùng khung Luật KDBĐS 2023 / Luật Nhà ở 2023)</td><td><strong>AP</strong></td></tr><tr><td>5</td><td>Điều khoản &amp; chính sách</td><td>—</td><td><strong>AP</strong> (soạn) / MAYogu (lập trình giao diện)</td></tr><tr><td>6</td><td>DPA (Data Processing Agreement)</td><td>NĐ 13/2023</td><td><strong>AP ký</strong> / MAYogu ký NDA-DPA</td></tr><tr><td>7</td><td>Dùng AI xử lý dữ liệu</td><td>NĐ 13/2023 (dữ liệu không ra nước ngoài)</td><td><strong>AP</strong> (chọn + chi trả hạ tầng VN)</td></tr><tr><td>8</td><td>ATTT cấp độ 3</td><td>— (sheet chưa nêu chi tiết)</td><td>🟡</td></tr><tr><td>9</td><td>Kết nối dữ liệu bên thứ 3</td><td>— (ngân hàng, vận chuyển, eKYC, SMS OTP)</td><td><strong>AP</strong> (chính) / MAYogu (kỹ thuật)</td></tr></tbody></table><hr><h2 id="_2-chi-tiet-tung-muc-nguyen-van-sheet-05" tabindex="-1">2. Chi tiết từng mục (nguyên văn Sheet 05) <a class="header-anchor" href="#_2-chi-tiet-tung-muc-nguyen-van-sheet-05" aria-label="Permalink to &quot;2. Chi tiết từng mục (nguyên văn Sheet 05)&quot;">​</a></h2><h3 id="muc-1-—-thu-thap-thong-tin-đinh-danh-·-fr-leg-01" tabindex="-1">Mục 1 — Thu thập thông tin định danh · <code>FR-LEG-01</code> <a class="header-anchor" href="#muc-1-—-thu-thap-thong-tin-đinh-danh-·-fr-leg-01" aria-label="Permalink to &quot;Mục 1 — Thu thập thông tin định danh · `FR-LEG-01`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td><strong>Nghị định 13/2023/NĐ-CP</strong> về bảo vệ dữ liệu cá nhân. <strong>CCCD + hồ sơ tài chính = dữ liệu cá nhân nhạy cảm.</strong> Yêu cầu <strong>consent opt-in</strong> (không tick sẵn), <strong>tách bạch mục đích</strong> thu thập; lập <strong>DPIA</strong> (Đánh giá tác động xử lý dữ liệu cá nhân) và <strong>nộp A05 – Bộ Công an trong 60 ngày</strong>; công bố <strong>Terms &amp; Privacy</strong>.</td></tr><tr><td><strong>AP</strong></td><td><strong>Chịu trách nhiệm chính</strong>; <strong>lập + nộp DPIA</strong> dưới tên doanh nghiệp CĐT.</td></tr><tr><td><strong>MAYogu</strong></td><td><strong>Giải trình kỹ thuật bảo mật</strong> (mã hóa, lưu trữ, phân quyền).</td></tr></tbody></table><blockquote><p>Liên quan trực tiếp Web NOXH: đăng ký bằng <strong>CCCD</strong> (bước 1), kê khai <strong>thu nhập/tình trạng nhà ở</strong> (bước 6), <strong>upload bản scan</strong> giấy tờ (bước 7) — tất cả là dữ liệu nhạy cảm. Cơ chế consent/opt-in, nơi lưu, mã hoá, phân quyền → xem <code>docs/04</code> §5 (phân quyền) + §8. 🟡 nhiều bước sheet ghi <strong>&quot;Check legal&quot;</strong> → OQ‑N1.</p></blockquote><h3 id="muc-2-—-đang-ky-mua-website-thuong-mai-đien-tu-·-fr-leg-02" tabindex="-1">Mục 2 — Đăng ký mua (website thương mại điện tử) · <code>FR-LEG-02</code> <a class="header-anchor" href="#muc-2-—-đang-ky-mua-website-thuong-mai-đien-tu-·-fr-leg-02" aria-label="Permalink to &quot;Mục 2 — Đăng ký mua (website thương mại điện tử) · `FR-LEG-02`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td>Phải <strong>đăng ký TMĐT với Bộ Công Thương (online.gov.vn)</strong> <strong>trước khi vận hành</strong>; <strong>công khai</strong>: Mã số thuế, địa chỉ, đại diện pháp luật, chính sách bảo vệ thông tin cá nhân, quy trình giải quyết tranh chấp, điều khoản sử dụng.</td></tr><tr><td><strong>AP</strong></td><td><strong>Đại diện đứng tên</strong>; <strong>chữ ký số</strong> của CĐT.</td></tr><tr><td><strong>MAYogu</strong></td><td><strong>Cung cấp tài liệu kỹ thuật / sơ đồ / quy trình</strong> phục vụ hồ sơ đăng ký.</td></tr></tbody></table><blockquote><p>Áp dụng cho cả 3 web (Web CĐT <code>docs/03</code>, Web NOXH <code>docs/04</code>, Web NOTM <code>docs/05</code>) vì đều thu thập thông tin/giao dịch với khách. 🟡 phạm vi đăng ký (từng site hay gộp) chưa nêu → OQ‑L2.</p></blockquote><h3 id="muc-3-—-minh-bach-thong-tin-·-fr-leg-03" tabindex="-1">Mục 3 — Minh bạch thông tin · <code>FR-LEG-03</code> <a class="header-anchor" href="#muc-3-—-minh-bach-thong-tin-·-fr-leg-03" aria-label="Permalink to &quot;Mục 3 — Minh bạch thông tin · `FR-LEG-03`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td><strong>Luật Kinh doanh Bất động sản 2023 &amp; Luật Nhà ở 2023.</strong> Thông tin công bố phải <strong>chính xác</strong>: quy hoạch 1/500, Giấy phép xây dựng (GPXD), quyền sử dụng đất, văn bản đủ điều kiện bán <strong>nhà ở hình thành trong tương lai (HTTTL)</strong>, <strong>bảo lãnh ngân hàng</strong>. <strong>Đặt cọc ≤ 5% giá bán</strong> khi đủ điều kiện kinh doanh. <strong>Cấm huy động vốn trái phép qua app.</strong> Xét duyệt NOXH theo Luật Nhà ở.</td></tr><tr><td><strong>AP</strong></td><td><strong>Chịu trách nhiệm chính.</strong></td></tr><tr><td><strong>MAYogu</strong></td><td><strong>Sau bàn giao, tool chỉ hỗ trợ kỹ thuật</strong> (không chịu trách nhiệm nội dung pháp lý).</td></tr></tbody></table><blockquote><p>Đây là ràng buộc hiển thị thông tin dự án: Web NOXH bước 2 (giá bán dự kiến/m², số căn) và Web CĐT (mục pháp lý dự án — QĐ 856/QĐ-UBND, quy hoạch 1/500, GPXD…). <strong>&quot;Đặt cọc ≤ 5%&quot;</strong> ràng buộc Web NOXH bước 18 (ký HĐ &amp; đặt cọc). <strong>&quot;Cấm huy động vốn trái phép qua app&quot;</strong> → lưu ý khi thiết kế luồng thanh toán. 🟡 OQ‑N8.</p></blockquote><h3 id="muc-4-—-bao-mat-va-an-toan-thong-tin-attt-·-fr-leg-04" tabindex="-1">Mục 4 — Bảo mật và An toàn thông tin (ATTT) · <code>FR-LEG-04</code> <a class="header-anchor" href="#muc-4-—-bao-mat-va-an-toan-thong-tin-attt-·-fr-leg-04" aria-label="Permalink to &quot;Mục 4 — Bảo mật và An toàn thông tin (ATTT) · `FR-LEG-04`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td>Cùng khung Luật KDBĐS 2023 / Luật Nhà ở 2023 (bảo mật, ATTT cho dữ liệu giao dịch &amp; khách hàng).</td></tr><tr><td><strong>AP</strong></td><td><strong>Chịu trách nhiệm chính.</strong></td></tr><tr><td><strong>MAYogu</strong></td><td><em>(sheet không ghi rõ — suy từ mục 1: giải trình kỹ thuật bảo mật)</em></td></tr></tbody></table><blockquote><p>Sheet gộp mục này với mục 1 về kỹ thuật bảo mật (mã hoá, lưu trữ, phân quyền). Chi tiết ATTT cấp độ 3 ở mục 8 (🟡 chưa nêu).</p></blockquote><h3 id="muc-5-—-đieu-khoan-chinh-sach-·-fr-leg-05" tabindex="-1">Mục 5 — Điều khoản &amp; chính sách · <code>FR-LEG-05</code> <a class="header-anchor" href="#muc-5-—-đieu-khoan-chinh-sach-·-fr-leg-05" aria-label="Permalink to &quot;Mục 5 — Điều khoản &amp; chính sách · `FR-LEG-05`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td>Các văn bản <strong>Điều khoản sử dụng, Chính sách bảo mật, Chính sách…</strong> hiển thị/cam kết trên website.</td></tr><tr><td><strong>AP</strong></td><td><strong>Dùng luật sư biên soạn</strong> nội dung.</td></tr><tr><td><strong>MAYogu</strong></td><td><strong>Lập trình giao diện</strong> (pop-up, nút tick <strong>Opt-in</strong>) <strong>đúng vị trí, bắt buộc thao tác</strong>.</td></tr></tbody></table><blockquote><p>Phân định rõ: <strong>nội dung = AP (luật sư)</strong>; <strong>kỹ thuật ép buộc thao tác = MAYogu</strong>. Yêu cầu kỹ thuật: nút opt-in <strong>không tick sẵn</strong> (khớp mục 1), pop-up đúng vị trí, <strong>bắt buộc</strong> khách thao tác trước khi tiếp tục (đăng ký / nộp hồ sơ).</p></blockquote><h3 id="muc-6-—-dpa-data-processing-agreement-·-fr-leg-06" tabindex="-1">Mục 6 — DPA (Data Processing Agreement) · <code>FR-LEG-06</code> <a class="header-anchor" href="#muc-6-—-dpa-data-processing-agreement-·-fr-leg-06" aria-label="Permalink to &quot;Mục 6 — DPA (Data Processing Agreement) · `FR-LEG-06`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td>Thoả thuận xử lý dữ liệu giữa CĐT và đơn vị phát triển (theo NĐ 13/2023).</td></tr><tr><td><strong>AP</strong></td><td><strong>Ký DPA với MAYogu.</strong></td></tr><tr><td><strong>MAYogu</strong></td><td><strong>Ký NDA/DPA</strong>; <strong>cam kết không trích xuất / mua bán / sử dụng dữ liệu khách của CĐT.</strong></td></tr></tbody></table><blockquote><p>Ràng buộc vận hành cho MAYogu: <strong>mọi dữ liệu khách (CCCD, hồ sơ, scan, lịch sử) thuộc sở hữu CĐT</strong>; MAYogu không được khai thác. Liên quan retention/xoá dữ liệu → 🟡 OQ‑C4 (<code>docs/02</code>).</p></blockquote><h3 id="muc-7-—-dung-ai-xu-ly-du-lieu-·-fr-leg-07" tabindex="-1">Mục 7 — Dùng AI xử lý dữ liệu · <code>FR-LEG-07</code> <a class="header-anchor" href="#muc-7-—-dung-ai-xu-ly-du-lieu-·-fr-leg-07" aria-label="Permalink to &quot;Mục 7 — Dùng AI xử lý dữ liệu · `FR-LEG-07`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td>Nếu dùng AI: <strong>AI local / On-Premise server tại Việt Nam</strong>, hoặc <strong>AI Cloud trong nước</strong> (<strong>FPT Cloud / Viettel AI / VNPT AI</strong>) với <strong>hạ tầng 100% tại Việt Nam</strong>; <strong>tránh chuyển dữ liệu ra nước ngoài</strong>.</td></tr><tr><td><strong>AP</strong></td><td><strong>Lựa chọn + chi trả hạ tầng server tại Việt Nam</strong>, <strong>đứng tên CĐT</strong>.</td></tr><tr><td><strong>MAYogu</strong></td><td><em>(triển khai kỹ thuật trên hạ tầng AP chọn)</em></td></tr></tbody></table><blockquote><p>Đây là <strong>ràng buộc bắt buộc</strong> nếu triển khai các 🔵 đề xuất dùng AI ở Web NOXH: <strong>AI kiểm tra sơ bộ hồ sơ</strong> (bước 10, OQ‑P1) và <strong>AI đối chiếu bản gốc</strong> (bước 13, OQ‑P1b) — xem <code>docs/04</code> §7. Không dùng dịch vụ AI có máy chủ nước ngoài. 🟡 OQ‑P1 cần CĐT xác nhận có triển khai AI hay không + chọn nhà cung cấp hạ tầng.</p></blockquote><h3 id="muc-8-—-an-toan-thong-tin-cap-đo-3-·-fr-leg-08" tabindex="-1">Mục 8 — An toàn thông tin cấp độ 3 · <code>FR-LEG-08</code> <a class="header-anchor" href="#muc-8-—-an-toan-thong-tin-cap-đo-3-·-fr-leg-08" aria-label="Permalink to &quot;Mục 8 — An toàn thông tin cấp độ 3 · `FR-LEG-08`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td><strong>&quot;ATTT cấp độ 3&quot;</strong> — sheet <strong>chỉ nêu tên, chưa có nội dung chi tiết</strong>.</td></tr><tr><td><strong>AP</strong></td><td>🟡 <em>(chưa ghi)</em></td></tr><tr><td><strong>MAYogu</strong></td><td>🟡 <em>(chưa ghi)</em></td></tr></tbody></table><blockquote><p>🟡 <strong>OQ‑L8</strong>: cần làm rõ yêu cầu <strong>ATTT cấp độ 3</strong> theo Nghị định 85/2016 (hệ thống thông tin cấp độ 3): phạm vi áp dụng (hệ thống nào), hồ sơ đề xuất cấp độ, phương án bảo đảm ATTT, ai lập/ai phê duyệt, thời điểm. <strong>Không tự suy diễn</strong> nội dung khi sheet chưa nêu.</p></blockquote><h3 id="muc-9-—-ket-noi-du-lieu-ben-thu-3-·-fr-leg-09" tabindex="-1">Mục 9 — Kết nối dữ liệu bên thứ 3 · <code>FR-LEG-09</code> <a class="header-anchor" href="#muc-9-—-ket-noi-du-lieu-ben-thu-3-·-fr-leg-09" aria-label="Permalink to &quot;Mục 9 — Kết nối dữ liệu bên thứ 3 · `FR-LEG-09`&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung (nguyên văn sheet)</th></tr></thead><tbody><tr><td><strong>Nội dung pháp lý</strong></td><td>Kết nối <strong>ngân hàng, vận chuyển, eKYC, SMS OTP</strong> — phải <strong>khả thi cả kỹ thuật + pháp lý</strong>.</td></tr><tr><td><strong>AP</strong></td><td><strong>Chịu trách nhiệm chính.</strong></td></tr><tr><td><strong>MAYogu</strong></td><td><strong>Triển khai kỹ thuật.</strong></td></tr></tbody></table><blockquote><p>Ánh xạ vào tính năng:</p><ul><li><strong>SMS OTP</strong> → Web NOXH/NOTM bước 1 (xác thực SĐT).</li><li><strong>eKYC</strong> → xác thực CCCD (🟡 sheet chưa nói rõ có dùng eKYC ở bước nào — cần xác nhận).</li><li><strong>Ngân hàng</strong> → Web NOXH bước 19 (ký hợp đồng ba bên, giải ngân).</li><li><strong>Vận chuyển</strong> → 🔵 Web NOXH bước 12 (liên kết đơn vị vận chuyển gửi bản gốc, OQ‑P2). Mỗi kết nối bên thứ 3 cần đánh giá <strong>pháp lý (chia sẻ dữ liệu, DPA với bên thứ 3)</strong> trước khi triển khai. 🟡 OQ‑L9.</li></ul></blockquote><hr><h2 id="_3-ma-tran-trach-nhiem-tong-hop-ap-↔-mayogu" tabindex="-1">3. Ma trận trách nhiệm tổng hợp (AP ↔ MAYogu) <a class="header-anchor" href="#_3-ma-tran-trach-nhiem-tong-hop-ap-↔-mayogu" aria-label="Permalink to &quot;3. Ma trận trách nhiệm tổng hợp (AP ↔ MAYogu)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hạng mục</th><th>AP (CĐT)</th><th>MAYogu (phát triển)</th></tr></thead><tbody><tr><td>Dữ liệu cá nhân (NĐ 13/2023)</td><td><strong>Chính</strong>: lập + nộp DPIA (A05, 60 ngày), đứng tên DN</td><td>Giải trình kỹ thuật bảo mật (mã hoá, lưu trữ, phân quyền)</td></tr><tr><td>Đăng ký TMĐT (online.gov.vn)</td><td><strong>Đại diện đứng tên</strong>, chữ ký số</td><td>Cung cấp tài liệu kỹ thuật / sơ đồ / quy trình</td></tr><tr><td>Minh bạch thông tin (KDBĐS/Nhà ở)</td><td><strong>Chính</strong> (nội dung công bố, đặt cọc ≤5%, bảo lãnh)</td><td>Sau bàn giao: tool chỉ hỗ trợ kỹ thuật</td></tr><tr><td>Điều khoản &amp; chính sách</td><td><strong>Luật sư biên soạn nội dung</strong></td><td>Lập trình giao diện (pop-up, opt-in bắt buộc)</td></tr><tr><td>DPA / NDA</td><td>Ký DPA với MAYogu</td><td>Ký NDA/DPA; không trích xuất/mua bán/dùng dữ liệu khách</td></tr><tr><td>AI xử lý dữ liệu</td><td><strong>Chọn + chi trả hạ tầng VN, đứng tên CĐT</strong></td><td>Triển khai kỹ thuật trên hạ tầng AP chọn</td></tr><tr><td>ATTT cấp độ 3</td><td>🟡 chưa rõ</td><td>🟡 chưa rõ</td></tr><tr><td>Kết nối bên thứ 3</td><td><strong>Chính</strong> (pháp lý)</td><td>Triển khai kỹ thuật</td></tr></tbody></table><p><strong>Nguyên tắc xuyên suốt (rút từ sheet):</strong></p><ul><li><strong>BR-LEG-01</strong>: <strong>AP chịu trách nhiệm pháp lý chính</strong> cho toàn bộ nội dung công bố, dữ liệu cá nhân, đăng ký TMĐT, kết nối bên thứ 3.</li><li><strong>BR-LEG-02</strong>: <strong>MAYogu chịu trách nhiệm kỹ thuật</strong> (giải trình bảo mật, lập trình giao diện cam kết/opt-in, triển khai tích hợp); <strong>sau bàn giao chỉ hỗ trợ kỹ thuật</strong>, không chịu trách nhiệm nội dung pháp lý.</li><li><strong>BR-LEG-03</strong>: <strong>Dữ liệu khách thuộc sở hữu CĐT</strong>; MAYogu không trích xuất/mua bán/sử dụng (DPA/NDA).</li><li><strong>BR-LEG-04</strong>: Nếu dùng <strong>AI</strong>, bắt buộc <strong>hạ tầng 100% tại Việt Nam</strong> (on-premise hoặc FPT Cloud/Viettel AI/VNPT AI); <strong>không chuyển dữ liệu ra nước ngoài</strong>.</li><li><strong>BR-LEG-05</strong>: <strong>Consent opt-in không tick sẵn, tách bạch mục đích</strong>; giao diện <strong>bắt buộc thao tác</strong> (pop-up/tick) đúng vị trí.</li><li><strong>BR-LEG-06</strong>: <strong>Đặt cọc ≤ 5% giá bán</strong> nhà ở HTTTL khi đủ điều kiện kinh doanh; <strong>cấm huy động vốn trái phép qua app</strong>.</li></ul><hr><h2 id="_4-viec-phap-ly-can-lam-truoc-van-hanh-checklist-suy-tu-sheet" tabindex="-1">4. Việc pháp lý cần làm trước vận hành (checklist suy từ sheet) <a class="header-anchor" href="#_4-viec-phap-ly-can-lam-truoc-van-hanh-checklist-suy-tu-sheet" aria-label="Permalink to &quot;4. Việc pháp lý cần làm trước vận hành (checklist suy từ sheet)&quot;">​</a></h2><blockquote><p>Đây là các hành động sheet nêu <strong>bắt buộc</strong>; không thêm yêu cầu ngoài sheet.</p></blockquote><ul><li>[ ] <strong>AP</strong> lập + nộp <strong>DPIA</strong> cho A05 – Bộ Công an <strong>trong 60 ngày</strong> (mục 1).</li><li>[ ] <strong>AP</strong> đăng ký <strong>TMĐT online.gov.vn</strong> trước khi vận hành; công khai MST/địa chỉ/đại diện pháp luật/chính sách bảo vệ thông tin/quy trình tranh chấp/điều khoản (mục 2).</li><li>[ ] <strong>AP</strong> (luật sư) biên soạn <strong>Terms &amp; Privacy &amp; Chính sách</strong>; <strong>MAYogu</strong> dựng pop-up/opt-in bắt buộc (mục 5).</li><li>[ ] <strong>AP ↔ MAYogu</strong> ký <strong>DPA/NDA</strong> (mục 6).</li><li>[ ] Nếu dùng <strong>AI</strong>: <strong>AP</strong> chọn + chi trả <strong>hạ tầng VN đứng tên CĐT</strong> (mục 7).</li><li>[ ] Xác định phạm vi <strong>ATTT cấp độ 3</strong> (mục 8 — 🟡 OQ‑L8).</li><li>[ ] Đánh giá pháp lý + kỹ thuật từng kết nối <strong>ngân hàng/vận chuyển/eKYC/SMS OTP</strong> (mục 9).</li></ul><hr><h2 id="_5-can-xac-nhan-bo-sung-đay-ve-docs-09" tabindex="-1">5. Cần xác nhận / bổ sung (đẩy về <code>docs/09</code>) <a class="header-anchor" href="#_5-can-xac-nhan-bo-sung-đay-ve-docs-09" aria-label="Permalink to &quot;5. Cần xác nhận / bổ sung (đẩy về `docs/09`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Nội dung</th><th>Mức</th></tr></thead><tbody><tr><td>OQ‑N1</td><td>Các bước Web NOXH sheet ghi <strong>&quot;Check legal&quot;</strong> (b1,6,7,10,12,13): pháp chế xác nhận</td><td>🟡</td></tr><tr><td>OQ‑L2</td><td>Phạm vi đăng ký TMĐT: đăng ký <strong>từng website</strong> hay gộp; site nào bắt buộc</td><td>🟡</td></tr><tr><td>OQ‑L8</td><td><strong>ATTT cấp độ 3</strong>: phạm vi, hồ sơ đề xuất cấp độ, phương án bảo đảm, ai lập/phê duyệt, thời điểm (mục 8 chưa chi tiết)</td><td>🟡</td></tr><tr><td>OQ‑L9</td><td><strong>eKYC</strong> dùng ở bước nào; DPA/chia sẻ dữ liệu với <strong>từng bên thứ 3</strong> (ngân hàng, vận chuyển, SMS OTP)</td><td>🟡</td></tr><tr><td>OQ‑P1</td><td>Có triển khai <strong>AI</strong> (kiểm tra sơ bộ hồ sơ + đối chiếu bản gốc) không; nếu có chọn <strong>nhà cung cấp hạ tầng VN</strong> nào (FPT/Viettel/VNPT)</td><td>🔵</td></tr><tr><td>OQ‑L5</td><td><strong>Nhà cung cấp chữ ký số</strong> cho CĐT (mục 2); ai quản lý</td><td>🟡</td></tr><tr><td>OQ‑L6</td><td><strong>Bảo lãnh ngân hàng</strong> cho nhà ở HTTTL (mục 3): ngân hàng nào, văn bản đã có chưa</td><td>🟡</td></tr></tbody></table><hr><h2 id="_6-tham-chieu" tabindex="-1">6. Tham chiếu <a class="header-anchor" href="#_6-tham-chieu" aria-label="Permalink to &quot;6. Tham chiếu&quot;">​</a></h2><ul><li><code>docs/00-project-context.md</code> §7 — vai trò (<code>ADMIN/STAFF/CUSTOMER/DOC/ACCOUNTANT</code>), glossary.</li><li><code>docs/04-web-noxh.md</code> — các bước sheet ghi &quot;Check legal&quot;, đề xuất AI (OQ‑P1/P1b), đặt cọc (b18), kết nối vận chuyển (b12), ngân hàng (b19).</li><li><code>docs/03-web-chu-dau-tu.md</code> — thông tin pháp lý dự án (QĐ 856/QĐ-UBND, quy hoạch 1/500, GPXD), minh bạch thông tin.</li><li><code>docs/02-phan-mem-tong-crm.md</code> — lưu trữ dữ liệu cá nhân/bản scan, retention (OQ‑C4).</li><li><code>docs/09-open-questions.md</code> — tổng hợp câu hỏi mở.</li></ul>',52)])])}const p=n(r,[["render",d]]);export{l as __pageData,p as default};
